.print "".print "╔════════════════════════════════════════════════════════════════╗".print "║  LISTA NOMINAL DE HIPERTENSÃO — NÚMEROS FINAIS                ║".print "║  Data de referência: 2026-08-01                               ║".print "╚════════════════════════════════════════════════════════════════╝".print "".print "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━".print "COORTE TOTAL".print "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"SELECT COUNT(*) total FROM mart_lista_nominal_hipertensao;.print "".print "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━".print "DISTRIBUIÇÃO POR BOA PRÁTICA".print "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"SELECT  'CONSULTA (6 meses)' pratica,  SUM(CASE WHEN consulta_status = 'EM_DIA' THEN 1 ELSE 0 END) em_dia,  SUM(CASE WHEN consulta_status = 'ATRASADA' THEN 1 ELSE 0 END) atrasada,  SUM(CASE WHEN consulta_status = 'NUNCA_REALIZADA' THEN 1 ELSE 0 END) nunca_realizada,  COUNT(*) totalFROM mart_lista_nominal_hipertensaoUNION ALLSELECT  'AFERIÇÃO PA (6 meses)',  SUM(CASE WHEN pa_status = 'EM_DIA' THEN 1 ELSE 0 END),  SUM(CASE WHEN pa_status = 'ATRASADA' THEN 1 ELSE 0 END),  SUM(CASE WHEN pa_status = 'NUNCA_REALIZADA' THEN 1 ELSE 0 END),  COUNT(*)FROM mart_lista_nominal_hipertensaoUNION ALLSELECT  'PESO + ALTURA (12 meses)',  SUM(CASE WHEN peso_altura_status = 'EM_DIA' THEN 1 ELSE 0 END),  SUM(CASE WHEN peso_altura_status = 'ATRASADA' THEN 1 ELSE 0 END),  SUM(CASE WHEN peso_altura_status = 'NUNCA_REALIZADA' THEN 1 ELSE 0 END),  COUNT(*)FROM mart_lista_nominal_hipertensao;.print "".print "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━".print "FILTRO: 'PELO MENOS UMA A FAZER' (qt_praticas_pendentes > 0)".print "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"SELECT  SUM(CASE WHEN qt_praticas_pendentes > 0 THEN 1 ELSE 0 END) pelo_menos_uma,  SUM(CASE WHEN qt_praticas_pendentes = 0 THEN 1 ELSE 0 END) todas_em_dia,  COUNT(*) totalFROM mart_lista_nominal_hipertensao;.print "".print "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━".print "DISTRIBUIÇÃO DE PRÁTICAS PENDENTES".print "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"SELECT qt_praticas_pendentes, COUNT(*) quantidadeFROM mart_lista_nominal_hipertensaoGROUP BY qt_praticas_pendentesORDER BY qt_praticas_pendentes;.print "".print "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━".print "COBERTURA DE DADOS CRÍTICOS (na coorte)".print "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"SELECT  COUNT(*) total,  SUM(CASE WHEN no_cidadao IS NULL THEN 1 ELSE 0 END) sem_nome,  SUM(CASE WHEN idade < 0 THEN 1 ELSE 0 END) idade_negativa,  COUNT(DISTINCT CASE WHEN pa_sistolica IS NOT NULL THEN 1 END) com_pa_sistolica,  COUNT(DISTINCT CASE WHEN pa_diastolica IS NOT NULL THEN 1 END) com_pa_diastolicaFROM mart_lista_nominal_hipertensao;.print "".print "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━".print "DISTRIBUIÇÃO POR EQUIPE (nu_ine)".print "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"SELECT nu_ine, no_equipe, COUNT(*) quantidadeFROM mart_lista_nominal_hipertensaoGROUP BY nu_ine, no_equipeORDER BY quantidade DESC;.print "".print "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━".print "FAIXA ETÁRIA".print "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"SELECT  CASE    WHEN idade < 0 THEN 'INVÁLIDA (< 0)'    WHEN idade < 30 THEN '< 30'    WHEN idade < 40 THEN '30-39'    WHEN idade < 50 THEN '40-49'    WHEN idade < 60 THEN '50-59'    WHEN idade < 70 THEN '60-69'    WHEN idade < 80 THEN '70-79'    ELSE '80+'  END faixa,  COUNT(*) quantidadeFROM mart_lista_nominal_hipertensaoGROUP BY faixaORDER BY  CASE faixa    WHEN 'INVÁLIDA (< 0)' THEN 0    WHEN '< 30' THEN 1    WHEN '30-39' THEN 2    WHEN '40-49' THEN 3    WHEN '50-59' THEN 4    WHEN '60-69' THEN 5    WHEN '70-79' THEN 6    ELSE 7  END;.print "".print "╔════════════════════════════════════════════════════════════════╗".print "║  FIM DOS NÚMEROS                                              ║".print "╚════════════════════════════════════════════════════════════════╝".print ""